#include <Cellerator/compiler/profile/expose_profile_inspection_and_diff_tooling_v1.hh>
#include <cassert>
#include <cstring>
int main(){using namespace cellerator::compiler::profile::v1;profile_inspection_state_v1 a{1,2,3,.9,0,4,1,2},b=a;b.evidence_revision=4;b.confidence=.8;b.maximum=5;b.expected_mutations=3;b.missing_evidence=0;char out[512];std::size_t n;assert(dump_profile_summary_v1(a,profile_inspection_format_v1::human,out,sizeof out,&n)==profile_inspection_status_v1::ok);assert(std::strstr(out,"confidence 0.900")&&std::strstr(out,"missing evidence 0x2"));assert(dump_profile_summary_v1(a,profile_inspection_format_v1::machine_json,out,sizeof out,&n)==profile_inspection_status_v1::ok);assert(std::strcmp(out,"{\"identity\":\"2:1\",\"revision\":3,\"confidence\":0.900,\"range\":[0.000,4.000],\"expected_mutations\":1,\"missing_evidence\":2}")==0);assert(diff_profile_states_v1(a,b,profile_inspection_format_v1::machine_json,out,sizeof out,&n)==profile_inspection_status_v1::ok);assert(std::strstr(out,"\"range_changed\":true")&&std::strstr(out,"\"missing_xor\":2"));}
